using System;
using System.IO;
using System.Reflection;
using System.Windows;
using System.Windows.Automation;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Threading;

namespace Mori {
 internal static class VideoControlsTests {
  static void Call(VideoPlayer player,string method,params object[] args){typeof(VideoPlayer).GetMethod(method,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(player,args);}
  static bool Near(double a,double b){return Math.Abs(a-b)<.0001;}
  internal static void Run(Action<bool,string> check){
   var volume=new VideoVolume();check(Near(volume.Effective,.7)&&!volume.Muted,"media uses the same initial volume in either decoder");volume.Set(.35);volume.Toggle();check(volume.Muted&&Near(volume.Level,.35)&&volume.Effective==0,"mute retains the selected volume");volume.Toggle();check(!volume.Muted&&Near(volume.Effective,.35),"unmute restores selected level rather than full volume");volume.Set(0);volume.Toggle();check(volume.Effective>0&&!volume.Muted,"unmute after zero slider restores audible volume");volume.Toggle();volume.Set(.25);check(!volume.Muted&&Near(volume.Effective,.25),"moving volume slider restores sound from mute");
   foreach(double value in new[]{-10.0,2.0,double.NaN,double.NegativeInfinity,double.PositiveInfinity}){volume.Set(value);check(volume.Level>=0&&volume.Level<=1&&!double.IsNaN(volume.Level),"volume rejects invalid or out-of-range level "+value);}
   var app=Application.Current??new Application();var previous=app.ShutdownMode;app.ShutdownMode=ShutdownMode.OnExplicitShutdown;string theme=Theme.Current;
   try{
    var window=new Window{Left=70,Top=80,Width=700,Height=450,WindowStyle=WindowStyle.SingleBorderWindow,ResizeMode=ResizeMode.CanResizeWithGrip};var full=new VideoFullscreen(window);
    full.Enter(new Rect(-1920,0,1920,1080));check(full.Active&&window.WindowStyle==WindowStyle.None&&window.ResizeMode==ResizeMode.NoResize&&window.Left==-1920&&window.Width==1920,"full screen targets supplied current monitor without rebuilding window");full.Enter(new Rect(0,0,500,400));check(window.Left==-1920&&window.Width==1920,"repeated full-screen enter does not overwrite saved bounds");full.Exit();check(!full.Active&&window.Left==70&&window.Top==80&&window.Width==700&&window.Height==450&&window.WindowStyle==WindowStyle.SingleBorderWindow&&window.ResizeMode==ResizeMode.CanResizeWithGrip,"leaving full screen restores exact normal bounds and border");full.Exit();check(window.Left==70&&window.Width==700,"repeated exit is harmless");window.WindowState=WindowState.Maximized;full.Enter(new Rect(0,0,1920,1080));full.Exit();check(window.WindowState==WindowState.Maximized,"full screen restores maximized state");window.Close();
    var player=new VideoPlayer(Path.Combine(Path.GetTempPath(),"mori-video-controls.mp4"));var host=new Window{Width=700,Height=450,Left=15,Top=25};player.AttachWindow(host);host.Content=player.Root;
    try{
     var decoder=player.Media;var root=player.Root;player.State.Open(12);player.State.Seek(6);int closed=0;player.CloseRequested+=delegate{closed++;};player.Screen.Enter(new Rect(0,0,1920,1080));player.BrowserKey("Escape");check(!player.Screen.Active&&closed==0,"focused-player Escape leaves full screen without closing preview");player.BrowserKey("Escape");check(closed==1,"ordinary focused-player Escape closes preview");player.BrowserKey("F11");check(player.Screen.Active&&closed==1,"focused-player F11 enters full screen");player.BrowserKey("F11");check(!player.Screen.Active&&ReferenceEquals(decoder,player.Media)&&ReferenceEquals(root,player.Root)&&player.State.Position==6,"F11 exit preserves decoder, controls and playback position");
     player.SetVolume(.42);check(Near(player.Media.Volume,.42)&&Near(player.Volume.Value,.42),"pre-ready volume immediately applies to native decoder");player.ToggleMute();check(player.Media.Volume==0&&Near(player.Volume.Value,.42),"mute never moves remembered slider level");player.Volume.Value=.2;check(!player.Sound.Muted&&Near(player.Sound.Effective,.2)&&Near(player.Media.Volume,.2),"slider value event drives native volume and unmutes");player.BrowserKey("M");check(player.Sound.Muted,"browser-focused M shares native mute control");player.BrowserKey("m");check(!player.Sound.Muted,"mute hotkey restores sound");
     foreach(string mode in new[]{"light","dark"}){Theme.Set(mode);player.Root.Measure(new Size(500,360));player.Root.Arrange(new Rect(0,0,500,360));player.Root.UpdateLayout();check(player.Progress.ActualWidth>=100&&player.Volume.ActualWidth>=55,"500px media bar preserves seek and volume hit areas / "+mode);check(player.Fullscreen.ActualWidth==32&&player.Play.ActualHeight==32,"compact media icons keep consistent size / "+mode);}
     foreach(var control in new FrameworkElement[]{player.Play,player.Mute,player.Volume,player.Fullscreen,player.Progress})check(!string.IsNullOrEmpty(AutomationProperties.GetName(control)),"media control has a readable accessible name / "+control.GetType().Name);
     foreach(var button in new[]{player.Play,player.Mute,player.Fullscreen})check(player.ControlOwnsKey(Key.Space,button),"focused media button keeps native Space activation / "+AutomationProperties.GetName(button));check(!player.ControlOwnsKey(Key.Space,player.Media)&&!player.ControlOwnsKey(Key.Space,null),"Space over playback surface remains the play/pause shortcut");foreach(var key in new[]{Key.Left,Key.Right,Key.Home,Key.End,Key.Up,Key.Down})check(player.ControlOwnsKey(key,player.Volume),"focused volume slider keeps native keyboard adjustment / "+key);check(!player.ControlOwnsKey(Key.Escape,player.Volume)&&!player.ControlOwnsKey(Key.F11,player.Fullscreen),"focused controls never intercept preview exit/fullscreen shortcuts");
     Call(player,"Fail");double position=player.State.Position;Call(player,"Opened",100.0);Call(player,"StartBrowser");check(player.Failed&&!player.Progress.IsEnabled&&!player.Play.IsEnabled&&!player.UsingBrowser&&player.State.Position==position,"late native open/failure after terminal failure cannot revive controls or create WebView");var timer=(DispatcherTimer)typeof(VideoPlayer).GetField("opening",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(player);check(!timer.IsEnabled&&!player.TimerRunning&&player.Media.Source==null,"terminal failure stops both load/progress timers and releases native source");
    }finally{player.Dispose();host.Content=null;host.Close();}
    var audio=new VideoPlayer(Path.Combine(Path.GetTempPath(),"mori-audio-controls.mp3"));var audioWindow=new Window{Width=500,Height=360};audio.AttachWindow(audioWindow);try{check(audio.Fullscreen.Visibility==Visibility.Collapsed&&!audio.Fullscreen.IsEnabled&&audio.Volume.Visibility==Visibility.Visible,"audio shows volume without an irrelevant video-fullscreen button");audio.BrowserKey("F11");check(!audio.Screen.Active,"audio focused F11 cannot enter video full screen");audio.SetVolume(.3);audio.ToggleMute();check(audio.Media.Volume==0&&Near(audio.Sound.Level,.3),"audio and video share the same volume/mute behavior");}finally{audio.Dispose();audioWindow.Close();}
    using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("Mori.Video.html"))using(var reader=new StreamReader(stream)){string html=reader.ReadToEnd();check(html.Contains("command.type==='volume'")&&html.Contains("video.muted=video.volume===0"),"browser player accepts bounded volume and restores muted state");check(html.Contains("'F11'")&&html.Contains("event.repeat"),"browser fullscreen and mute hotkeys prevent held-key toggle storms");check(html.Contains("'dblclick',()=>send('close')"),"browser doubleclick remains close, not unexpected fullscreen toggle");}
   }finally{if(!string.IsNullOrEmpty(theme))Theme.Set(theme);app.ShutdownMode=previous;}
  }
  // Run only in an already-created isolated decoder fixture, never the user's UI.
  internal static void BrowserVolume(VideoPlayer player,Action<bool,string> check){
   double effective=player.Sound.Effective;player.Toggle();player.Toggle();Probe(player,"Math.abs(video.volume-"+effective.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+")<.0001&&video.muted==="+(effective==0?"true":"false"),check,"playback transition restores current user volume after thumbnail extraction");player.SetVolume(.31);Probe(player,"Math.abs(video.volume-.31)<.0001&&!video.muted",check,"real browser decoder receives slider volume");player.ToggleMute();Probe(player,"video.muted&&video.volume===0",check,"real browser decoder mutes without resetting remembered level");player.ToggleMute();Probe(player,"!video.muted&&Math.abs(video.volume-.31)<.0001",check,"real browser decoder restores selected volume");
  }
  static void Probe(VideoPlayer player,string script,Action<bool,string> check,string label){var task=player.Browser.View.CoreWebView2.ExecuteScriptAsync(script);var watch=System.Diagnostics.Stopwatch.StartNew();while(!task.IsCompleted&&watch.ElapsedMilliseconds<3000){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(20)};timer.Tick+=delegate{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}check(task.IsCompleted&&!task.IsFaulted&&task.Result=="true",label);}
 }
}
